import json, sys, os

def trunc(s, n=220):
    s = s.replace('\n', ' ⏎ ')
    return s if len(s) <= n else s[:n] + '...'

def summarize_content_block(b):
    t = b.get('type')
    if t == 'text':
        return f"[text] {trunc(b.get('text',''))}"
    if t == 'tool_use':
        name = b.get('name')
        inp = b.get('input', {})
        inp_s = trunc(json.dumps(inp, ensure_ascii=False), 200)
        return f"[tool_use:{name}] {inp_s}"
    if t == 'tool_result':
        content = b.get('content')
        if isinstance(content, list):
            texts = []
            for c in content:
                if isinstance(c, dict) and c.get('type') == 'text':
                    texts.append(c.get('text', ''))
            content = ' '.join(texts)
        content = str(content)
        err = b.get('is_error', False)
        return f"[tool_result{'ERR' if err else ''}] {trunc(content, 200)}"
    return f"[{t}] {trunc(json.dumps(b, ensure_ascii=False), 150)}"

def main(path):
    out = []
    with open(path) as fh:
        for lineno, line in enumerate(fh):
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            typ = d.get('type')
            ts = d.get('timestamp', '')
            if typ == 'user':
                msg = d.get('message', {})
                content = msg.get('content')
                utype = d.get('userType')
                if isinstance(content, str):
                    out.append(f"{ts} HUMAN({utype}): {trunc(content, 500)}")
                elif isinstance(content, list):
                    for b in content:
                        if isinstance(b, dict):
                            s = summarize_content_block(b)
                            if s.startswith('[tool_result'):
                                out.append(f"{ts} {s}")
            elif typ == 'assistant':
                msg = d.get('message', {})
                content = msg.get('content')
                usage = msg.get('usage', {})
                if isinstance(content, list):
                    for b in content:
                        if isinstance(b, dict):
                            s = summarize_content_block(b)
                            out.append(f"{ts} {s}")
            elif typ == 'attachment':
                att = d.get('attachment', {})
                hook = att.get('hookName') or att.get('type')
                out.append(f"{ts} ATTACHMENT[{hook}]: {trunc(str(att.get('content','')), 150)}")
            elif typ == 'system':
                out.append(f"{ts} SYSTEM: {trunc(str(d.get('content','')), 150)}")
    return out

if __name__ == '__main__':
    path = sys.argv[1]
    outpath = sys.argv[2] if len(sys.argv) > 2 else None
    lines = main(path)
    text = '\n'.join(lines)
    if outpath:
        with open(outpath, 'w') as f:
            f.write(text)
        print(f"wrote {len(lines)} lines to {outpath}, {len(text)} chars")
    else:
        print(text)

